mapper.select:
SELECT COUNT(*)
  FROM doctor_schedule
 WHERE doctor_id = #{doctorId}
   AND schedule_date = #{scheduleDate}
   AND period = #{period}

   AND id <> #{excludeScheduleId}

SELECT COUNT(*)
  FROM doctor
 WHERE id = #{doctorId}
   AND department_id = #{departmentId}
   AND status = 1
   AND deleted = 0

mapper.delete:
DELETE FROM doctor_schedule
 WHERE id = #{id}
   AND booked_count = 0
